import itertools, sys
sys.path.insert(0,'/tmp/reduction-8p7km_4p')
from problems import ThreeSat, DominatingSet

def min_dom(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    best=n+1
    for r in range(n+1):
        for comb in itertools.combinations(range(n), r):
            S=set(comb)
            dom=set(S)
            for u in S: dom|=adj[u]
            if len(dom)==n:
                return r
    return best

def tri_reduce(inst):
    m=inst['num_vars']; clauses=inst['clauses']
    def lv(l):
        b=2*(abs(l)-1); return b if l>0 else b+1
    edges=[[2*(v-1),2*(v-1)+1] for v in range(1,m+1)]
    nxt=2*m
    for cl in clauses:
        t0,t1,t2=nxt,nxt+1,nxt+2; nxt+=3
        edges+=[[t0,t1],[t1,t2],[t0,t2]]
        for tv,l in zip((t0,t1,t2),cl): edges.append([tv,lv(l)])
    return nxt,edges,m+len(clauses)

def clause_reduce(inst):
    m=inst['num_vars']; clauses=inst['clauses']
    def lv(l):
        b=2*(abs(l)-1); return b if l>0 else b+1
    edges=[[2*(v-1),2*(v-1)+1] for v in range(1,m+1)]
    nxt=2*m
    for cl in clauses:
        c=nxt; nxt+=1
        for l in cl: edges.append([c,lv(l)])
    return nxt,edges,m

